dashboard.definition:
{
  "title": "Offline devices",
  "description": "Devices that are not online, how long, and whether many went offline together.",
  "inputs": {
    "input_time": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "tr",
        "defaultValue": "-24h,now"
      }
    },
    "input_site": {
      "type": "input.text",
      "title": "Site (wildcard)",
      "options": {
        "token": "site",
        "defaultValue": "*"
      }
    },
    "input_thr": {
      "type": "input.text",
      "title": "Many-offline threshold (%)",
      "options": {
        "token": "thr",
        "defaultValue": "50"
      }
    },
    "input_flap": {
      "type": "input.text",
      "title": "Flapping: state changes",
      "options": {
        "token": "flap",
        "defaultValue": "4"
      }
    }
  },
  "dataSources": {
    "ds_total": {
      "type": "ds.search",
      "name": "Devices",
      "options": {
        "query": "`aruba_central_index` ((sourcetype=\"aruba:central:ap\") OR (sourcetype=\"aruba:central:device\" deviceType!=\"ACCESS_POINT\")) earliest=-2h\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| eval type=if(sourcetype=\"aruba:central:ap\",\"ACCESS_POINT\",deviceType)\n| stats latest(status) as status latest(_time) as last_poll latest(deviceName) as name latest(model) as model latest(siteName) as site latest(type) as type by serialNumber\n| stats count"
      }
    },
    "ds_off": {
      "type": "ds.search",
      "name": "Offline",
      "options": {
        "query": "`aruba_central_index` ((sourcetype=\"aruba:central:ap\") OR (sourcetype=\"aruba:central:device\" deviceType!=\"ACCESS_POINT\")) earliest=-2h\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| eval type=if(sourcetype=\"aruba:central:ap\",\"ACCESS_POINT\",deviceType)\n| stats latest(status) as status latest(_time) as last_poll latest(deviceName) as name latest(model) as model latest(siteName) as site latest(type) as type by serialNumber\n| where status!=\"ONLINE\" | stats count"
      }
    },
    "ds_pct": {
      "type": "ds.search",
      "name": "Offline share",
      "options": {
        "query": "`aruba_central_index` ((sourcetype=\"aruba:central:ap\") OR (sourcetype=\"aruba:central:device\" deviceType!=\"ACCESS_POINT\")) earliest=-2h\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| eval type=if(sourcetype=\"aruba:central:ap\",\"ACCESS_POINT\",deviceType)\n| stats latest(status) as status latest(_time) as last_poll latest(deviceName) as name latest(model) as model latest(siteName) as site latest(type) as type by serialNumber\n| stats count as total count(eval(status!=\"ONLINE\")) as off\n| eval pct=if(total>0,round(100*off/total,1),0)\n| fields pct"
      }
    },
    "ds_list": {
      "type": "ds.search",
      "name": "Offline devices",
      "options": {
        "query": "`aruba_central_index` ((sourcetype=\"aruba:central:ap\") OR (sourcetype=\"aruba:central:device\" deviceType!=\"ACCESS_POINT\"))\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| eval type=if(sourcetype=\"aruba:central:ap\",\"ACCESS_POINT\",deviceType)\n| rename siteName as site, deviceName as name\n| stats latest(status) as status latest(name) as name latest(model) as model latest(site) as site latest(type) as type max(eval(if(status=\"ONLINE\",_time,null()))) as last_online latest(_time) as last_poll by serialNumber\n| where status!=\"ONLINE\"\n| eval \"Last online\"=if(isnull(last_online),\"not online in the time range\",strftime(last_online,\"%Y-%m-%d %H:%M\")), \"Offline for\"=if(isnull(last_online),\"-\",tostring(now()-last_online,\"duration\")), \"Last poll\"=strftime(last_poll,\"%Y-%m-%d %H:%M\")\n| table serialNumber name type model site status \"Last online\" \"Offline for\" \"Last poll\"\n| sort type site name"
      }
    },
    "ds_sites": {
      "type": "ds.search",
      "name": "Sites",
      "options": {
        "query": "`aruba_central_index` ((sourcetype=\"aruba:central:ap\") OR (sourcetype=\"aruba:central:device\" deviceType!=\"ACCESS_POINT\")) earliest=-2h\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| eval type=if(sourcetype=\"aruba:central:ap\",\"ACCESS_POINT\",deviceType)\n| stats latest(status) as status latest(_time) as last_poll latest(deviceName) as name latest(model) as model latest(siteName) as site latest(type) as type by serialNumber\n| stats count as devices count(eval(status!=\"ONLINE\")) as offline by site\n| where offline>0\n| eval offline_pct=round(100*offline/devices,1)\n| eval Assessment=if(offline_pct>=$thr$ AND offline>=3,\"Many devices offline at once: check uplink, power and Central status\",\"\")\n| sort - offline_pct\n| rename site as Site, devices as Devices, offline as Offline, offline_pct as \"Offline %\""
      }
    },
    "ds_wave": {
      "type": "ds.search",
      "name": "Went offline",
      "options": {
        "query": "`aruba_central_index` ((sourcetype=\"aruba:central:ap\") OR (sourcetype=\"aruba:central:device\" deviceType!=\"ACCESS_POINT\"))\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| eval type=if(sourcetype=\"aruba:central:ap\",\"ACCESS_POINT\",deviceType)\n| rename siteName as site, deviceName as name\n| sort 0 serialNumber _time\n| streamstats current=f last(status) as prev by serialNumber\n| where status!=\"ONLINE\" AND prev=\"ONLINE\"\n| timechart minspan=5m dc(serialNumber) as devices_went_offline dc(site) as sites"
      }
    },
    "ds_flap": {
      "type": "ds.search",
      "name": "Flapping",
      "options": {
        "query": "`aruba_central_index` ((sourcetype=\"aruba:central:ap\") OR (sourcetype=\"aruba:central:device\" deviceType!=\"ACCESS_POINT\"))\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| eval type=if(sourcetype=\"aruba:central:ap\",\"ACCESS_POINT\",deviceType)\n| rename siteName as site, deviceName as name\n| sort 0 serialNumber _time\n| streamstats current=f last(status) as prev by serialNumber\n| where isnotnull(prev) AND status!=prev\n| stats count as state_changes latest(name) as name latest(type) as type latest(model) as model latest(site) as site by serialNumber\n| where state_changes>=$flap$\n| sort - state_changes\n| table serialNumber name type model site state_changes\n| rename state_changes as \"State changes\""
      }
    }
  },
  "visualizations": {
    "v_total": {
      "type": "splunk.singlevalue",
      "title": "Devices",
      "dataSources": {
        "primary": "ds_total"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "v_off": {
      "type": "splunk.singlevalue",
      "title": "Offline now",
      "dataSources": {
        "primary": "ds_off"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "v_pct": {
      "type": "splunk.singlevalue",
      "title": "Offline share",
      "dataSources": {
        "primary": "ds_pct"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "unit": "%",
        "unitPosition": "after"
      }
    },
    "v_list": {
      "type": "splunk.table",
      "title": "Offline devices",
      "dataSources": {
        "primary": "ds_list"
      },
      "options": {
        "count": 10
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/aruba_central_poc/access_point?form.serial=$row.serialNumber.value$&form.site=*",
            "newTab": false
          }
        }
      ]
    },
    "v_sites": {
      "type": "splunk.table",
      "title": "Sites with offline devices",
      "dataSources": {
        "primary": "ds_sites"
      },
      "options": {
        "count": 8
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/aruba_central_poc/alerts?form.site=$row.Site.value$&form.severity=*",
            "newTab": false
          }
        }
      ]
    },
    "v_wave": {
      "type": "splunk.column",
      "title": "Devices that went offline (5 minute bins)",
      "dataSources": {
        "primary": "ds_wave"
      },
      "options": {
        "x": "> primary | seriesByName('_time')",
        "legendDisplay": "bottom",
        "y": "> primary | frameBySeriesNames('devices_went_offline', 'sites')"
      }
    },
    "v_flap": {
      "type": "splunk.table",
      "title": "Devices that changed state often",
      "dataSources": {
        "primary": "ds_flap"
      },
      "options": {
        "count": 8
      }
    },
    "v_note": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "Access points come from the Wireless input, switches and gateways from the Inventory input (hourly by default), so their status can be up to an hour old. Many devices going offline together, especially across several sites, points to a connectivity or Central problem and not to a failure at each site. Compare with a second source (ping, SNMP, syslog) before you act.",
        "fontSize": "small"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$tr.earliest$",
            "latest": "$tr.latest$"
          }
        }
      }
    }
  },
  "layout": {
    "globalInputs": [
      "input_time",
      "input_site",
      "input_thr",
      "input_flap"
    ],
    "layoutDefinitions": {
      "layout_1": {
        "type": "absolute",
        "options": {
          "width": 1200,
          "height": 1320
        },
        "structure": [
          {
            "item": "v_total",
            "type": "block",
            "position": {
              "x": 0,
              "y": 0,
              "w": 390,
              "h": 150
            }
          },
          {
            "item": "v_off",
            "type": "block",
            "position": {
              "x": 400,
              "y": 0,
              "w": 390,
              "h": 150
            }
          },
          {
            "item": "v_pct",
            "type": "block",
            "position": {
              "x": 800,
              "y": 0,
              "w": 390,
              "h": 150
            }
          },
          {
            "item": "v_list",
            "type": "block",
            "position": {
              "x": 0,
              "y": 170,
              "w": 1200,
              "h": 340
            }
          },
          {
            "item": "v_sites",
            "type": "block",
            "position": {
              "x": 0,
              "y": 530,
              "w": 590,
              "h": 320
            }
          },
          {
            "item": "v_wave",
            "type": "block",
            "position": {
              "x": 610,
              "y": 530,
              "w": 590,
              "h": 320
            }
          },
          {
            "item": "v_flap",
            "type": "block",
            "position": {
              "x": 0,
              "y": 870,
              "w": 1200,
              "h": 300
            }
          },
          {
            "item": "v_note",
            "type": "block",
            "position": {
              "x": 0,
              "y": 1190,
              "w": 1200,
              "h": 110
            }
          }
        ]
      }
    },
    "options": {
      "submitButton": false
    },
    "tabs": {
      "items": [
        {
          "layoutId": "layout_1",
          "label": "Offline devices"
        }
      ]
    }
  }
}
